<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  :root {
    --bg: #12141c;
    --board-bg: #1c1f2b;
    --cell-bg: #2a2e3d;
    --text: #e8e8e8;
    --accent: #f0b429;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    background: var(--bg);
    color: var(--text);
    font-family: "Segoe UI", system-ui, Arial, sans-serif;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 20px;
    min-height: 100vh;
  }
  h1 {
    margin: 0;
    font-size: 48px;
    letter-spacing: 2px;
    color: var(--accent);
  }
  .topbar {
    display: flex;
    align-items: center;
    gap: 16px;
  }
  .scorebox {
    background: var(--board-bg);
    padding: 10px 18px;
    border-radius: 8px;
    text-align: center;
    min-width: 90px;
  }
  .scorebox .label {
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 1px;
    opacity: 0.7;
  }
  #score {
    font-size: 26px;
    font-weight: bold;
  }
  #reset {
    background: var(--accent);
    color: #12141c;
    border: none;
    padding: 12px 20px;
    font-size: 16px;
    font-weight: bold;
    border-radius: 8px;
    cursor: pointer;
  }
  #reset:hover { filter: brightness(1.1); }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(4, 1fr);
    gap: 12px;
    background: var(--board-bg);
    padding: 12px;
    border-radius: 12px;
    width: 440px;
    height: 440px;
  }
  .cell {
    background: var(--cell-bg);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 34px;
    font-weight: bold;
    color: var(--text);
    user-select: none;
  }
  .cell[data-v="0"] { color: transparent; }
  .cell[data-v="2"]    { background: #3a4055; }
  .cell[data-v="4"]    { background: #46506e; }
  .cell[data-v="8"]    { background: #d98b3a; color: #fff; }
  .cell[data-v="16"]   { background: #e07b39; color: #fff; }
  .cell[data-v="32"]   { background: #e5603a; color: #fff; }
  .cell[data-v="64"]   { background: #e33f2e; color: #fff; }
  .cell[data-v="128"]  { background: #edc850; color: #fff; font-size: 28px; }
  .cell[data-v="256"]  { background: #edc23f; color: #fff; font-size: 28px; }
  .cell[data-v="512"]  { background: #edbe2e; color: #fff; font-size: 28px; }
  .cell[data-v="1024"] { background: #edb91d; color: #fff; font-size: 22px; }
  .cell[data-v="2048"] { background: #edb60c; color: #fff; font-size: 22px; }
  .hint { opacity: 0.6; font-size: 14px; }
</style>
</head>
<body>
  <h1>2048</h1>
  <div class="topbar">
    <div class="scorebox">
      <div class="label">Score</div>
      <div id="score">0</div>
    </div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>
  <div class="hint">Use the arrow keys to move the tiles.</div>

<script>
(function () {
  const SIZE = 4;
  let grid = [];
  let scoreVal = 0;
  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');

  function emptyGrid() {
    return Array.from({ length: SIZE }, () => new Array(SIZE).fill(0));
  }

  function emptyCells() {
    const cells = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (grid[r][c] === 0) cells.push([r, c]);
    return cells;
  }

  function spawnTile() {
    const cells = emptyCells();
    if (cells.length === 0) return false;
    const [r, c] = cells[Math.floor(Math.random() * cells.length)];
    grid[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  // Slide + merge a single row toward the left (index 0).
  // Returns { row, gained } where row is the new length-SIZE array.
  function slideRowLeft(row) {
    const nums = row.filter(v => v !== 0);
    const out = [];
    let gained = 0;
    for (let i = 0; i < nums.length; i++) {
      if (i + 1 < nums.length && nums[i] === nums[i + 1]) {
        const merged = nums[i] * 2;
        out.push(merged);
        gained += merged;
        i++; // skip the consumed partner — at most one merge per tile
      } else {
        out.push(nums[i]);
      }
    }
    while (out.length < SIZE) out.push(0);
    return { row: out, gained };
  }

  function cloneGrid(g) {
    return g.map(row => row.slice());
  }

  function gridsEqual(a, b) {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return false;
    return true;
  }

  // Transform grid so that the requested direction becomes "left",
  // apply slideRowLeft to each row, then transform back.
  function move(dir) {
    const before = cloneGrid(grid);
    let working;

    if (dir === 'left') {
      working = grid.map(row => row.slice());
    } else if (dir === 'right') {
      working = grid.map(row => row.slice().reverse());
    } else if (dir === 'up') {
      working = transpose(grid);
    } else if (dir === 'down') {
      working = transpose(grid).map(row => row.slice().reverse());
    } else {
      return false;
    }

    let gained = 0;
    working = working.map(row => {
      const res = slideRowLeft(row);
      gained += res.gained;
      return res.row;
    });

    let result;
    if (dir === 'left') {
      result = working;
    } else if (dir === 'right') {
      result = working.map(row => row.reverse());
    } else if (dir === 'up') {
      result = transpose(working);
    } else if (dir === 'down') {
      result = transpose(working.map(row => row.reverse()));
    }

    if (gridsEqual(before, result)) {
      return false;
    }

    grid = result;
    scoreVal += gained;
    spawnTile();
    render();
    return true;
  }

  function transpose(g) {
    const t = emptyGrid();
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        t[c][r] = g[r][c];
    return t;
  }

  function reset() {
    grid = emptyGrid();
    scoreVal = 0;
    spawnTile();
    spawnTile();
    render();
  }

  function render() {
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const v = grid[r][c];
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.setAttribute('data-v', v);
        cell.textContent = v === 0 ? '' : v;
        boardEl.appendChild(cell);
      }
    }
    scoreEl.textContent = scoreVal;
  }

  document.addEventListener('keydown', function (e) {
    let dir = null;
    switch (e.key) {
      case 'ArrowLeft':  dir = 'left';  break;
      case 'ArrowRight': dir = 'right'; break;
      case 'ArrowUp':    dir = 'up';    break;
      case 'ArrowDown':  dir = 'down';  break;
      default: return;
    }
    e.preventDefault();
    move(dir);
  });

  document.getElementById('reset').addEventListener('click', reset);

  // Programmatic API for grading.
  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: function () { return cloneGrid(grid); },
    setBoard: function (arr) {
      grid = arr.map(row => row.slice());
      render();
    },
    score: function () { return scoreVal; }
  };

  reset();
})();
</script>
</body>
</html>
